/* ================= CALENDAR (month grid + agenda + pageants + directing) ================= */
function CalendarTab({ B, events, saveEvents, pageants, savePageants, clients, directing, saveDirecting, initialView = "month" }) {
  const { Field, input, Primary, Ghost, chip, card } = useBrandBits(B);
  const [view, setView] = useState(initialView);
  const [adding, setAdding] = useState(false);
  const blank = { type: "lesson", title: "", clientName: "", date: "", time: "", durMin: 60, notes: "" };
  const [form, setForm] = useState(blank);
  const today = new Date().toISOString().slice(0, 10);
  const [cursor, setCursor] = useState(() => { const d = new Date(); return new Date(d.getFullYear(), d.getMonth(), 1); });
  const [selDay, setSelDay] = useState(today);

  /* all items, past and future */
  const allItems = [
    ...events.map((e) => ({ ...e, kind: "event" })),
    ...pageants.filter((p) => p.date).map((p) => ({
      id: p.id, kind: "pageant", type: "pageant", title: p.name, date: p.date, time: "",
      notes: [p.system && `System: ${p.system}`, p.director && `Director: ${p.director}`, `${(p.girls || []).length} girls competing`].filter(Boolean).join(" · "),
      location: p.location || "",
    })),
    ...directing.filter((d) => d.date).map((d) => ({
      id: d.id, kind: "directing", type: "pageant", title: `${d.name} (directing)`, date: d.date, time: "", notes: d.notes || "", location: d.location || "",
    })),
  ];
  const sortItems = (a, b) => a.date.localeCompare(b.date) || (EVENT_TYPES[a.type]?.rank ?? 9) - (EVENT_TYPES[b.type]?.rank ?? 9) || (a.time || "99").localeCompare(b.time || "99");
  const agenda = allItems.filter((e) => e.date >= today).sort(sortItems);
  const byDate = {};
  allItems.forEach((e) => { (byDate[e.date] = byDate[e.date] || []).push(e); });
  Object.values(byDate).forEach((l) => l.sort(sortItems));

  const prettyDay = (d) => {
    const dt = new Date(d + "T12:00");
    const label = dt.toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric" });
    return d === today ? `Today · ${label}` : label;
  };

  const addEvent = async () => {
    if (!form.title.trim() || !form.date) return;
    await saveEvents([...events, { ...form, id: "e" + Date.now(), durMin: Number(form.durMin) || 60 }]);
    setForm(blank); setAdding(false);
  };
  const toIphone = (e) => downloadICS(`${e.title.replace(/[^a-z0-9]/gi, "-").toLowerCase()}.ics`,
    [{ title: `${e.title}${e.clientName ? ` — ${e.clientName}` : ""}`, date: e.date, time: e.time || "", durMin: e.durMin, notes: e.notes, location: e.location }]);
  const exportAll = () => agenda.length && downloadICS("paige-hq-schedule.ics",
    agenda.map((e) => ({ title: `${e.title}${e.clientName ? ` — ${e.clientName}` : ""}`, date: e.date, time: e.time || "", durMin: e.durMin, notes: e.notes, location: e.location })));

  const ItemCard = (e) => (
    <div key={e.kind + e.id} style={{ ...card, padding: "13px 15px", marginBottom: 8, borderLeft: `2px solid ${isBizType(e.type) ? B.c.accent : e.type === "pageant" ? B.c.gold : B.c.line}` }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 8 }}>
        <div style={{ fontWeight: 500, fontSize: 14.5 }}>
          <span style={{ color: B.c.accent, marginRight: 6 }}>{EVENT_TYPES[e.type]?.mark}</span>
          {e.title}{e.clientName ? <span style={{ fontWeight: 300, color: B.c.faint }}> · {e.clientName}</span> : null}
        </div>
        <div className="hq-mono" style={{ fontSize: 10, letterSpacing: 1, color: B.c.faint, whiteSpace: "nowrap" }}>{prettyTime(e.time)}</div>
      </div>
      {e.notes && <div style={{ fontSize: 12.5, fontWeight: 300, color: B.c.faint, marginTop: 3 }}>{e.notes}</div>}
      <div style={{ display: "flex", gap: 16, marginTop: 8 }}>
        <button onClick={() => toIphone(e)} className="hq-mono" style={{ border: "none", background: "none", color: B.c.accent, fontSize: 9.5, letterSpacing: 2, padding: 0, fontWeight: 500 }}>ADD TO IPHONE</button>
        {e.kind === "event" && (
          <button onClick={() => saveEvents(events.filter((x) => x.id !== e.id))} className="hq-mono" style={{ border: "none", background: "none", color: B.c.faint, fontSize: 9.5, letterSpacing: 2, padding: 0 }}>REMOVE</button>
        )}
      </div>
    </div>
  );

  /* month grid */
  const y = cursor.getFullYear(), m = cursor.getMonth();
  const firstDow = new Date(y, m, 1).getDay();
  const daysInMonth = new Date(y, m + 1, 0).getDate();
  const cells = [...Array(firstDow).fill(null), ...Array.from({ length: daysInMonth }, (_, i) => `${y}-${pad(m + 1)}-${pad(i + 1)}`)];
  const monthLabel = cursor.toLocaleDateString("en-US", { month: "long", year: "numeric" });
  const dotColor = (t) => (isBizType(t) ? B.c.accent : t === "pageant" ? B.c.gold : "#B9B2A4");

  const AddForm = () => (
    <div className="hq-fade" style={{ ...card, padding: 18, marginBottom: 16 }}>
      <Field label="Type">
        <select style={input} value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value })}>
          {Object.entries(EVENT_TYPES).filter(([k]) => k !== "pageant").map(([k, v]) => <option key={k} value={k}>{v.label}</option>)}
        </select>
      </Field>
      <Field label="Title"><input style={input} value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} placeholder={form.type === "tan" ? "Signature glow" : form.type === "lesson" ? "One-hour coaching" : form.type === "dance" ? "Dance lesson" : form.type === "showing" ? "Showing · address" : form.type === "emcee" ? "Emceeing · Bluegrass State Classic" : "Event name"} /></Field>
      {(form.type === "lesson" || form.type === "tan" || form.type === "dance" || form.type === "client" || form.type === "showing") && (
        <Field label="Client">
          <input style={input} list="hq-clients" value={form.clientName} onChange={(e) => setForm({ ...form, clientName: e.target.value })} placeholder="Who is it for?" />
          <datalist id="hq-clients">{clients.map((c) => <option key={c.id} value={c.name} />)}</datalist>
        </Field>
      )}
      <div style={{ display: "flex", gap: 10 }}>
        <div style={{ flex: 1.2 }}><Field label="Date"><input style={input} type="date" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} /></Field></div>
        <div style={{ flex: 1 }}><Field label="Time"><input style={input} type="time" value={form.time} onChange={(e) => setForm({ ...form, time: e.target.value })} /></Field></div>
        <div style={{ flex: 0.7 }}><Field label="Mins"><input style={input} type="number" value={form.durMin} onChange={(e) => setForm({ ...form, durMin: e.target.value })} /></Field></div>
      </div>
      <Field label="Notes"><input style={input} value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} placeholder="Optional" /></Field>
      <Primary onClick={addEvent} disabled={!form.title.trim() || !form.date}>Save</Primary>
    </div>
  );

  return (
    <div className="hq-fade">
      <div style={{ display: "flex", gap: 6, marginBottom: 16 }}>
        {[["month", "MONTH"], ["lesson", "LESSONS"], ["tan", "TANNING"], ["dance", "DANCE"], ["pageants", "PAGEANTS"]].map(([v, lab]) => (
          <button key={v} className="hq-mono" style={{ ...chip(view === v), flex: 1, textAlign: "center", padding: "7px 4px", fontSize: 8.5 }} onClick={() => setView(v)}>{lab}</button>
        ))}
      </div>

      {view !== "pageants" && (
        <div style={{ display: "flex", gap: 8, marginBottom: 16 }}>
          <Primary onClick={() => { setAdding(!adding); if (!adding && view === "month") setForm({ ...form, date: selDay }); }} style={{ flex: 1, padding: "13px 10px", fontSize: 11 }}>{adding ? "Cancel" : "Add to schedule"}</Primary>
          <Ghost onClick={exportAll} disabled={agenda.length === 0} style={{ flex: 1, textAlign: "center" }}>Send to iPhone</Ghost>
        </div>
      )}
      {adding && view !== "pageants" && <AddForm />}

      {view === "month" && (
        <>
          {/* month header */}
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
            <button onClick={() => setCursor(new Date(y, m - 1, 1))} className="hq-mono" style={{ border: `1px solid ${B.c.line}`, background: B.c.card, color: B.c.ink, borderRadius: 4, padding: "6px 14px", fontSize: 13 }}>‹</button>
            <div style={{ fontFamily: B.display, fontSize: 20, fontWeight: 600 }}>{monthLabel}</div>
            <button onClick={() => setCursor(new Date(y, m + 1, 1))} className="hq-mono" style={{ border: `1px solid ${B.c.line}`, background: B.c.card, color: B.c.ink, borderRadius: 4, padding: "6px 14px", fontSize: 13 }}>›</button>
          </div>

          {/* weekday header */}
          <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", marginBottom: 4 }}>
            {["S", "M", "T", "W", "T", "F", "S"].map((d, i) => (
              <div key={i} className="hq-mono" style={{ textAlign: "center", fontSize: 9, letterSpacing: 1, color: B.c.faint, padding: "4px 0" }}>{d}</div>
            ))}
          </div>

          {/* grid */}
          <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 3, marginBottom: 16 }}>
            {cells.map((d, i) => {
              if (!d) return <div key={"b" + i} />;
              const items = byDate[d] || [];
              const isToday = d === today;
              const isSel = d === selDay;
              return (
                <button key={d} onClick={() => setSelDay(d)}
                  style={{
                    aspectRatio: "1 / 1.05", border: `1px solid ${isSel ? B.c.accent : B.c.line}`, borderRadius: 6,
                    background: isSel ? B.c.deep : B.c.card, color: isSel ? B.c.gold : isToday ? B.c.accent : B.c.ink,
                    display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 3, padding: 2,
                  }}>
                  <span className="hq-mono" style={{ fontSize: 12, fontWeight: isToday || isSel ? 600 : 400 }}>{Number(d.slice(-2))}</span>
                  <span style={{ display: "flex", gap: 2, height: 5 }}>
                    {items.slice(0, 3).map((it, j) => (
                      <span key={j} style={{ width: 4, height: 4, borderRadius: "50%", background: isSel ? B.c.gold : dotColor(it.type) }} />
                    ))}
                  </span>
                </button>
              );
            })}
          </div>

          {/* selected day */}
          <div style={{ fontFamily: B.display, fontSize: 16, fontWeight: 600, color: selDay === today ? B.c.accent : B.c.ink, marginBottom: 2 }}>{prettyDay(selDay)}</div>
          <hr className="lux-rule" style={{ margin: "0 0 10px" }} />
          {(byDate[selDay] || []).length === 0 && (
            <p style={{ fontSize: 13.5, fontWeight: 300, color: B.c.faint }}>Nothing scheduled this day — tap "Add to schedule" to book it.</p>
          )}
          {(byDate[selDay] || []).map(ItemCard)}
        </>
      )}

      {["lesson", "tan", "dance"].includes(view) && (() => {
        const typed = agenda.filter((e) => e.type === view);
        const groups = Object.entries(typed.reduce((acc, e) => { (acc[e.date] = acc[e.date] || []).push(e); return acc; }, {}));
        const emptyMsg = view === "lesson" ? "No pageant lessons on the books yet." : view === "tan" ? "No tans on the books yet." : "No dance lessons on the books yet.";
        return (
          <>
            {typed.length === 0 && !adding && (
              <div style={{ textAlign: "center", padding: "40px 20px", color: B.c.faint }}>
                <div style={{ fontFamily: B.display, fontSize: 30, color: B.c.accent }}>{EVENT_TYPES[view].mark}</div>
                <p style={{ fontSize: 14, fontWeight: 300 }}>{emptyMsg}</p>
              </div>
            )}
            {groups.map(([day, list]) => (
              <div key={day} style={{ marginBottom: 18 }}>
                <div style={{ fontFamily: B.display, fontSize: 16, fontWeight: 600, color: day === today ? B.c.accent : B.c.ink, marginBottom: 2 }}>{prettyDay(day)}</div>
                <hr className="lux-rule" style={{ margin: "0 0 10px" }} />
                {list.map(ItemCard)}
              </div>
            ))}
          </>
        );
      })()}

      {view === "pageants" && <PageantsPane B={B} pageants={pageants} savePageants={savePageants} />}
    </div>
  );
}

/* ================= DIRECTING ================= */
function DirectingPane({ B, directing, saveDirecting }) {
  const { Field, input, Primary, card, H } = useBrandBits(B);
  const [open, setOpen] = useState(null);
  const [adding, setAdding] = useState(false);
  const blank = { name: "", date: "", location: "", notes: "" };
  const [form, setForm] = useState(blank);

  const totals = (d) => {
    const fees = (d.entries || []).reduce((s, e) => s + (e.paid ? (e.fee || 0) : 0), 0);
    const feesDue = (d.entries || []).reduce((s, e) => s + (!e.paid ? (e.fee || 0) : 0), 0);
    const other = (d.income || []).reduce((s, i) => s + (i.amount || 0), 0);
    const exp = (d.expenses || []).reduce((s, x) => s + (x.amount || 0), 0);
    return { fees, feesDue, other, exp, net: fees + other - exp };
  };

  const addDirected = async () => {
    if (!form.name.trim()) return;
    await saveDirecting([...directing, { ...form, id: "d" + Date.now(), entries: [], income: [], expenses: [] }]);
    setForm(blank); setAdding(false);
  };

  return (
    <>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
        <H size={20}>Productions</H>
        <button onClick={() => setAdding(!adding)} className="hq-mono"
          style={{ padding: "8px 16px", borderRadius: 3, border: "none", background: B.c.deep, color: B.c.gold, fontSize: 10, letterSpacing: 2 }}>
          {adding ? "CANCEL" : "+ ADD"}
        </button>
      </div>
      <p style={{ fontSize: 13, fontWeight: 300, color: B.c.faint, margin: "0 0 14px" }}>
        The production ledger — entry fees, concessions, and event expenses for each pageant.
      </p>

      {adding && (
        <div className="hq-fade" style={{ ...card, padding: 18, marginBottom: 16 }}>
          <Field label="Pageant name"><input style={input} value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></Field>
          <div style={{ display: "flex", gap: 10 }}>
            <div style={{ flex: 1 }}><Field label="Date"><input style={input} type="date" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} /></Field></div>
            <div style={{ flex: 1 }}><Field label="Venue"><input style={input} value={form.location} onChange={(e) => setForm({ ...form, location: e.target.value })} /></Field></div>
          </div>
          <Primary onClick={addDirected} disabled={!form.name.trim()}>Save</Primary>
        </div>
      )}

      {directing.map((d) => {
        const t = totals(d);
        return (
          <button key={d.id} onClick={() => setOpen(d.id)}
            style={{ ...card, width: "100%", textAlign: "left", padding: "16px 17px", marginBottom: 12, borderLeft: `2px solid ${B.c.accent}`, cursor: "pointer" }}>
            <div style={{ fontFamily: B.display, fontWeight: 600, fontSize: 19 }}><span style={{ color: B.c.accent }}>♛</span> {d.name}</div>
            <div className="hq-mono" style={{ fontSize: 10, letterSpacing: 1, color: B.c.faint, margin: "4px 0 10px" }}>
              {d.date || "DATE TBD"}{d.location ? ` · ${d.location.toUpperCase()}` : ""} · {(d.entries || []).length} CONTESTANTS
            </div>
            <div style={{ display: "flex", gap: 14, flexWrap: "wrap" }}>
              {[["FEES IN", money(t.fees)], ["CONCESSIONS+", money(t.other)], ["EXPENSES", money(t.exp)], ["NET", money(t.net)]].map(([lab, val]) => (
                <div key={lab}>
                  <div className="hq-mono" style={{ fontSize: 13, fontWeight: 500, color: lab === "NET" ? (t.net >= 0 ? "#4E6B4E" : "#8A4646") : B.c.ink }}>{val}</div>
                  <div className="hq-mono" style={{ fontSize: 7.5, letterSpacing: 1.5, color: B.c.faint, marginTop: 1 }}>{lab}</div>
                </div>
              ))}
            </div>
          </button>
        );
      })}

      {open && (
        <DirectedDetail B={B} d={directing.find((x) => x.id === open)} totals={totals} onClose={() => setOpen(null)}
          onChange={async (u) => saveDirecting(directing.map((x) => (x.id === u.id ? u : x)))}
          onDelete={async () => { await saveDirecting(directing.filter((x) => x.id !== open)); setOpen(null); }} />
      )}
    </>
  );
}

function DirectedDetail({ B, d, totals, onClose, onChange, onDelete }) {
  const { input, chip } = useBrandBits(B);
  const [sub, setSub] = useState("entries");
  const [entry, setEntry] = useState({ name: "", division: "", fee: "" });
  const [line, setLine] = useState({ date: new Date().toISOString().slice(0, 10), desc: "", amount: "" });
  if (!d) return null;
  const t = totals(d);

  const addEntry = () => {
    if (!entry.name.trim()) return;
    onChange({ ...d, entries: [...(d.entries || []), { id: "n" + Date.now(), ...entry, fee: Number(entry.fee) || 0, paid: false }] });
    setEntry({ name: "", division: "", fee: "" });
  };
  const togglePaid = (id) => onChange({ ...d, entries: d.entries.map((e) => (e.id === id ? { ...e, paid: !e.paid } : e)) });
  const addLine = (key) => {
    if (!line.desc.trim() || !line.amount) return;
    onChange({ ...d, [key]: [...(d[key] || []), { id: "l" + Date.now(), ...line, amount: Number(line.amount) || 0 }] });
    setLine({ date: new Date().toISOString().slice(0, 10), desc: "", amount: "" });
  };

  return (
    <Sheet B={B} onClose={onClose}>
      <div style={{ fontFamily: B.display, fontSize: 24, fontWeight: 600 }}><span style={{ color: B.c.accent }}>♛</span> {d.name}</div>
      <div className="hq-mono" style={{ fontSize: 10, letterSpacing: 1.5, color: B.c.faint, margin: "5px 0 12px" }}>
        {d.date || "DATE TBD"}{d.location ? ` · ${d.location.toUpperCase()}` : ""}
      </div>

      <div style={{ display: "flex", gap: 12, flexWrap: "wrap", background: B.c.card, border: `1px solid ${B.c.line}`, borderRadius: 8, padding: "12px 14px", marginBottom: 14 }}>
        {[["FEES COLLECTED", money(t.fees)], ["FEES DUE", money(t.feesDue)], ["CONCESSIONS+", money(t.other)], ["EXPENSES", money(t.exp)], ["NET", money(t.net)]].map(([lab, val]) => (
          <div key={lab}>
            <div className="hq-mono" style={{ fontSize: 13.5, fontWeight: 500, color: lab === "NET" ? (t.net >= 0 ? "#4E6B4E" : "#8A4646") : lab === "FEES DUE" && t.feesDue > 0 ? "#8A6D3B" : B.c.ink }}>{val}</div>
            <div className="hq-mono" style={{ fontSize: 7.5, letterSpacing: 1.5, color: B.c.faint, marginTop: 1 }}>{lab}</div>
          </div>
        ))}
      </div>

      <div style={{ display: "flex", gap: 7, marginBottom: 14 }}>
        {[["entries", "ENTRIES"], ["income", "CONCESSIONS+"], ["expenses", "EXPENSES"]].map(([v, lab]) => (
          <button key={v} className="hq-mono" style={{ ...chip(sub === v), flex: 1, textAlign: "center", fontSize: 9 }} onClick={() => setSub(v)}>{lab}</button>
        ))}
      </div>

      {sub === "entries" && (
        <>
          {(d.entries || []).map((e) => (
            <div key={e.id} style={{ display: "flex", alignItems: "center", gap: 10, background: B.c.card, border: `1px solid ${B.c.line}`, borderRadius: 6, padding: "10px 12px", marginBottom: 8 }}>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontWeight: 500, fontSize: 14 }}>{e.name}</div>
                <div className="hq-mono" style={{ fontSize: 9, letterSpacing: 1.5, color: B.c.faint, marginTop: 1 }}>{(e.division || "—").toUpperCase()} · {money(e.fee)}</div>
              </div>
              <button onClick={() => togglePaid(e.id)} className="hq-mono"
                style={{ padding: "5px 11px", borderRadius: 2, fontSize: 9, letterSpacing: 1.5, border: `1px solid ${e.paid ? "#4E6B4E" : "#8A6D3B"}`, background: "transparent", color: e.paid ? "#4E6B4E" : "#8A6D3B" }}>
                {e.paid ? "PAID" : "DUE"}
              </button>
              <button onClick={() => onChange({ ...d, entries: d.entries.filter((x) => x.id !== e.id) })} style={{ border: "none", background: "none", color: B.c.faint, fontSize: 15, padding: 2 }}>✕</button>
            </div>
          ))}
          {(d.entries || []).length === 0 && <p style={{ fontSize: 13, fontWeight: 300, color: B.c.faint }}>No contestants entered yet.</p>}
          <div style={{ display: "flex", gap: 8, marginTop: 8, marginBottom: 8 }}>
            <input style={{ ...input, flex: 1.3 }} placeholder="Contestant" value={entry.name} onChange={(e) => setEntry({ ...entry, name: e.target.value })} />
            <input style={{ ...input, flex: 1 }} placeholder="Division" value={entry.division} onChange={(e) => setEntry({ ...entry, division: e.target.value })} />
            <input className="hq-mono" style={{ ...input, flex: 0.7 }} type="number" placeholder="Fee $" value={entry.fee} onChange={(e) => setEntry({ ...entry, fee: e.target.value })} />
          </div>
          <button onClick={addEntry} disabled={!entry.name.trim()}
            style={{ width: "100%", padding: 13, borderRadius: 4, border: "none", background: entry.name.trim() ? B.c.accent : "#CBC2B4", color: "#fff", fontWeight: 500, fontSize: 12, letterSpacing: 2, textTransform: "uppercase" }}>
            Add contestant
          </button>
          <p style={{ fontSize: 11.5, fontWeight: 300, color: B.c.faint, marginTop: 8 }}>Tap DUE to mark an entry fee as received — only paid fees count toward the totals.</p>
        </>
      )}

      {(sub === "income" || sub === "expenses") && (
        <>
          {(d[sub] || []).map((l) => (
            <div key={l.id} style={{ display: "flex", alignItems: "center", gap: 10, background: B.c.card, border: `1px solid ${B.c.line}`, borderRadius: 6, padding: "10px 12px", marginBottom: 8 }}>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontWeight: 500, fontSize: 14 }}>{l.desc}</div>
                <div className="hq-mono" style={{ fontSize: 9, letterSpacing: 1.5, color: B.c.faint, marginTop: 1 }}>{l.date}</div>
              </div>
              <span className="hq-mono" style={{ fontWeight: 500, fontSize: 13.5, color: sub === "income" ? "#4E6B4E" : B.c.ink }}>{money(l.amount)}</span>
              <button onClick={() => onChange({ ...d, [sub]: d[sub].filter((x) => x.id !== l.id) })} style={{ border: "none", background: "none", color: B.c.faint, fontSize: 15, padding: 2 }}>✕</button>
            </div>
          ))}
          {(d[sub] || []).length === 0 && (
            <p style={{ fontSize: 13, fontWeight: 300, color: B.c.faint }}>
              {sub === "income" ? "Concessions, ad pages, vendor tables, program sales — log every dollar in." : "Venue, crowns, sashes, judges, trophies, printing — log every dollar out."}
            </p>
          )}
          <div style={{ display: "flex", gap: 8, marginTop: 8, marginBottom: 8 }}>
            <input style={{ ...input, flex: 1 }} type="date" value={line.date} onChange={(e) => setLine({ ...line, date: e.target.value })} />
            <input style={{ ...input, flex: 1.4 }} placeholder={sub === "income" ? "Concessions night 1…" : "Venue rental…"} value={line.desc} onChange={(e) => setLine({ ...line, desc: e.target.value })} />
            <input className="hq-mono" style={{ ...input, flex: 0.7 }} type="number" step="0.01" placeholder="$" value={line.amount} onChange={(e) => setLine({ ...line, amount: e.target.value })} />
          </div>
          <button onClick={() => addLine(sub)} disabled={!line.desc.trim() || !line.amount}
            style={{ width: "100%", padding: 13, borderRadius: 4, border: "none", background: line.desc.trim() && line.amount ? B.c.accent : "#CBC2B4", color: "#fff", fontWeight: 500, fontSize: 12, letterSpacing: 2, textTransform: "uppercase" }}>
            {sub === "income" ? "Record income" : "Record expense"}
          </button>
        </>
      )}

      <div style={{ display: "flex", gap: 10, marginTop: 18 }}>
        <button onClick={onClose} style={{ flex: 1, padding: 13, borderRadius: 4, border: `1px solid ${B.c.deep}`, background: "transparent", color: B.c.deep, fontWeight: 500, fontSize: 11, letterSpacing: 2, textTransform: "uppercase" }}>Close</button>
        <button onClick={onDelete} style={{ flex: 1, padding: 13, borderRadius: 4, border: "1px solid #8A4646", background: "transparent", color: "#8A4646", fontWeight: 500, fontSize: 11, letterSpacing: 2, textTransform: "uppercase" }}>Delete</button>
      </div>
    </Sheet>
  );
}

/* ================= PAGEANTS ================= */
function PageantsPane({ B, pageants, savePageants }) {
  const { Field, input, Primary, card, H } = useBrandBits(B);
  const blank = { name: "", date: "", location: "", director: "", system: "", notes: "" };
  const [adding, setAdding] = useState(false);
  const [form, setForm] = useState(blank);
  const [open, setOpen] = useState(null);
  const today = new Date().toISOString().slice(0, 10);

  const upcoming = pageants.filter((p) => (p.date || "9999") >= today).sort((a, b) => (a.date || "").localeCompare(b.date || ""));
  const past = pageants.filter((p) => (p.date || "9999") < today).sort((a, b) => (b.date || "").localeCompare(a.date || ""));
  const daysOut = (d) => { if (!d) return null; const n = Math.ceil((new Date(d + "T12:00") - new Date()) / 86400000); return n >= 0 ? n : null; };

  const addPageant = async () => {
    if (!form.name.trim()) return;
    await savePageants([...pageants, { ...form, id: "p" + Date.now(), girls: [] }]);
    setForm(blank); setAdding(false);
  };

  const Card = ({ p, dim }) => (
    <button onClick={() => setOpen(p.id)}
      style={{ ...card, width: "100%", textAlign: "left", padding: "15px 17px", marginBottom: 12, borderLeft: `2px solid ${dim ? B.c.line : B.c.accent}`, opacity: dim ? 0.65 : 1, cursor: "pointer" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 8 }}>
        <div style={{ fontFamily: B.display, fontWeight: 600, fontSize: 18 }}><span style={{ color: B.c.accent }}>♛</span> {p.name}</div>
        {daysOut(p.date) !== null && !dim && (
          <span className="hq-mono" style={{ fontSize: 9, letterSpacing: 2, color: B.c.accent, fontWeight: 500, whiteSpace: "nowrap" }}>
            {daysOut(p.date) === 0 ? "TODAY" : `IN ${daysOut(p.date)} DAYS`}
          </span>
        )}
      </div>
      <div className="hq-mono" style={{ fontSize: 10, letterSpacing: 1, color: B.c.faint, marginTop: 4 }}>{p.date || "DATE TBD"}{p.location ? ` · ${p.location.toUpperCase()}` : ""}</div>
      <div style={{ fontSize: 13, fontWeight: 300, marginTop: 5 }}>
        {p.system && <span>{p.system} · </span>}{p.director && <span>Director {p.director} · </span>}
        <span style={{ fontWeight: 500 }}>{(p.girls || []).length}</span> girl{(p.girls || []).length === 1 ? "" : "s"} competing
      </div>
    </button>
  );

  return (
    <>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
        <H size={20}>Upcoming pageants</H>
        <button onClick={() => setAdding(!adding)} className="hq-mono"
          style={{ padding: "8px 16px", borderRadius: 3, border: "none", background: B.c.deep, color: B.c.gold, fontSize: 10, letterSpacing: 2 }}>
          {adding ? "CANCEL" : "+ ADD"}
        </button>
      </div>

      {adding && (
        <div className="hq-fade" style={{ ...card, padding: 18, marginBottom: 16 }}>
          <Field label="Pageant name"><input style={input} value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="e.g., Miss Kentucky Preteen" /></Field>
          <div style={{ display: "flex", gap: 10 }}>
            <div style={{ flex: 1 }}><Field label="Date"><input style={input} type="date" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} /></Field></div>
            <div style={{ flex: 1 }}><Field label="Location"><input style={input} value={form.location} onChange={(e) => setForm({ ...form, location: e.target.value })} placeholder="City / venue" /></Field></div>
          </div>
          <div style={{ display: "flex", gap: 10 }}>
            <div style={{ flex: 1 }}><Field label="Director"><input style={input} value={form.director} onChange={(e) => setForm({ ...form, director: e.target.value })} /></Field></div>
            <div style={{ flex: 1 }}><Field label="System"><input style={input} value={form.system} onChange={(e) => setForm({ ...form, system: e.target.value })} placeholder="Natural, Glitz…" /></Field></div>
          </div>
          <Field label="Notes"><textarea style={{ ...input, minHeight: 60 }} value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} placeholder="Entry deadlines, fees, wardrobe…" /></Field>
          <Primary onClick={addPageant} disabled={!form.name.trim()}>Save pageant</Primary>
        </div>
      )}

      {pageants.length === 0 && !adding && (
        <div style={{ textAlign: "center", padding: "40px 20px", color: B.c.faint }}>
          <div style={{ fontFamily: B.display, fontSize: 30, color: B.c.accent }}>♛</div>
          <p style={{ fontSize: 14, fontWeight: 300 }}>No pageants yet — add the next one and begin the roster.</p>
        </div>
      )}

      {upcoming.map((p) => <Card key={p.id} p={p} />)}
      {past.length > 0 && (
        <>
          <div className="hq-mono" style={{ fontSize: 9, letterSpacing: 3, color: B.c.faint, margin: "18px 0 10px" }}>PAST</div>
          {past.map((p) => <Card key={p.id} p={p} dim />)}
        </>
      )}

      {open && (
        <PageantDetail B={B} pageant={pageants.find((x) => x.id === open)} onClose={() => setOpen(null)}
          onChange={async (u) => savePageants(pageants.map((x) => (x.id === u.id ? u : x)))}
          onDelete={async () => { await savePageants(pageants.filter((x) => x.id !== open)); setOpen(null); }} />
      )}
    </>
  );
}

function PageantDetail({ B, pageant, onClose, onChange, onDelete }) {
  const { input, Ghost } = useBrandBits(B);
  const [girl, setGirl] = useState({ name: "", category: "" });
  if (!pageant) return null;
  const girls = pageant.girls || [];
  const addGirl = () => {
    if (!girl.name.trim()) return;
    onChange({ ...pageant, girls: [...girls, { id: "g" + Date.now(), ...girl }] });
    setGirl({ name: "", category: "" });
  };
  return (
    <Sheet B={B} onClose={onClose}>
      <div style={{ fontFamily: B.display, fontSize: 24, fontWeight: 600 }}><span style={{ color: B.c.accent }}>♛</span> {pageant.name}</div>
      <div className="hq-mono" style={{ fontSize: 10, letterSpacing: 1.5, color: B.c.faint, margin: "6px 0 4px" }}>{pageant.date || "DATE TBD"}{pageant.location ? ` · ${pageant.location.toUpperCase()}` : ""}</div>
      <div style={{ fontSize: 13.5, fontWeight: 300, marginBottom: 8 }}>
        {pageant.system && <span><b style={{ fontWeight: 500 }}>System</b> {pageant.system} &nbsp;</span>}
        {pageant.director && <span><b style={{ fontWeight: 500 }}>Director</b> {pageant.director}</span>}
      </div>
      {pageant.notes && <p style={{ fontSize: 13.5, lineHeight: 1.6, fontWeight: 300, background: B.c.card, borderLeft: `2px solid ${B.c.accent}`, padding: "10px 14px", borderRadius: 4 }}>{pageant.notes}</p>}
      {pageant.date && (
        <Ghost onClick={() => downloadICS(`${pageant.name.replace(/[^a-z0-9]/gi, "-").toLowerCase()}.ics`, [{ title: `♛ ${pageant.name}`, date: pageant.date, notes: pageant.notes, location: pageant.location }])} style={{ marginTop: 4 }}>
          Add to iPhone calendar
        </Ghost>
      )}

      <div className="hq-mono" style={{ fontSize: 9, letterSpacing: 3, color: B.c.faint, margin: "18px 0 10px" }}>COMPETING · {girls.length}</div>
      {girls.map((g) => (
        <div key={g.id} style={{ display: "flex", alignItems: "center", gap: 12, background: B.c.card, border: `1px solid ${B.c.line}`, borderRadius: 6, padding: "10px 13px", marginBottom: 8 }}>
          <Monogram B={B} text={g.name.trim().charAt(0).toUpperCase()} size={34} />
          <div style={{ flex: 1 }}>
            <div style={{ fontWeight: 500, fontSize: 14.5 }}>{g.name}</div>
            {g.category && <div className="hq-mono" style={{ fontSize: 9, letterSpacing: 2, color: B.c.accent, marginTop: 1 }}>{g.category.toUpperCase()}</div>}
          </div>
          <button onClick={() => onChange({ ...pageant, girls: girls.filter((x) => x.id !== g.id) })} aria-label={`Remove ${g.name}`} style={{ border: "none", background: "none", color: B.c.faint, fontSize: 16, padding: 4 }}>✕</button>
        </div>
      ))}
      {girls.length === 0 && <p style={{ fontSize: 13, fontWeight: 300, color: B.c.faint, margin: "4px 0 10px" }}>No girls on the roster yet.</p>}

      <div style={{ display: "flex", gap: 8, marginTop: 6 }}>
        <input style={{ ...input, flex: 1.2 }} placeholder="Girl's name" value={girl.name} onChange={(e) => setGirl({ ...girl, name: e.target.value })} />
        <input style={{ ...input, flex: 1 }} placeholder="Category / division" value={girl.category} onChange={(e) => setGirl({ ...girl, category: e.target.value })} onKeyDown={(e) => e.key === "Enter" && addGirl()} />
      </div>
      <button onClick={addGirl} disabled={!girl.name.trim()}
        style={{ width: "100%", marginTop: 10, padding: 13, borderRadius: 4, border: "none", background: girl.name.trim() ? B.c.accent : "#CBC2B4", color: "#fff", fontWeight: 500, fontSize: 12, letterSpacing: 2, textTransform: "uppercase" }}>
        Add to roster
      </button>

      <div style={{ display: "flex", gap: 10, marginTop: 18 }}>
        <button onClick={onClose} style={{ flex: 1, padding: 13, borderRadius: 4, border: `1px solid ${B.c.deep}`, background: "transparent", color: B.c.deep, fontWeight: 500, fontSize: 11, letterSpacing: 2, textTransform: "uppercase" }}>Close</button>
        <button onClick={onDelete} style={{ flex: 1, padding: 13, borderRadius: 4, border: "1px solid #8A4646", background: "transparent", color: "#8A4646", fontWeight: 500, fontSize: 11, letterSpacing: 2, textTransform: "uppercase" }}>Delete</button>
      </div>
    </Sheet>
  );
}

/* ================= CLIENT PORTAL ================= */
function ClientPortal({ client, events, saveEvents, pageants, onExit }) {
  const B = client.biz?.PP ? BRANDS.pp : client.biz?.VG ? BRANDS.vg : BRANDS.re;
  const { input } = useBrandBits(B);
  const today = new Date().toISOString().slice(0, 10);
  const [ev, setEv] = useState({ title: "", date: "", time: "" });
  const [added, setAdded] = useState(false);

  const firstName = client.name.trim().split(" ")[0];
  const mine = events.filter((e) => (e.clientName || "").toLowerCase() === client.name.toLowerCase());
  const upcoming = mine.filter((e) => e.date >= today).sort((a, b) => a.date.localeCompare(b.date) || (a.time || "").localeCompare(b.time || ""));
  const myPageants = client.biz?.PP
    ? pageants.filter((p) => (p.girls || []).some((g) => g.name.toLowerCase() === client.name.toLowerCase()) && (p.date || "9999") >= today)
        .sort((a, b) => (a.date || "").localeCompare(b.date || ""))
    : [];
  const history = (client.history || []).slice().sort((a, b) => (b.date || "").localeCompare(a.date || ""));
  const daysOut = (d) => Math.ceil((new Date(d + "T12:00") - new Date()) / 86400000);
  const prettyDate = (d) => new Date(d + "T12:00").toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric" });

  const addMyEvent = async () => {
    if (!ev.title.trim() || !ev.date) return;
    await saveEvents([...events, { id: "e" + Date.now(), type: "client", title: ev.title, clientName: client.name, date: ev.date, time: ev.time, durMin: 60, notes: "Added by client via portal" }]);
    setEv({ title: "", date: "", time: "" });
    setAdded(true); setTimeout(() => setAdded(false), 2500);
  };

  const SectionLabel = ({ children }) => (
    <div className="hq-mono" style={{ fontSize: 9, letterSpacing: 3, color: B.c.faint, margin: "20px 0 10px" }}>{children}</div>
  );
  const card = { background: B.c.card, borderRadius: 8, border: `1px solid ${B.c.line}` };
  const infoRow = (label, val) => val ? (
    <div style={{ display: "flex", gap: 10, fontSize: 13.5, marginBottom: 5 }}>
      <span className="hq-mono" style={{ fontSize: 9, letterSpacing: 2, color: B.c.faint, minWidth: 92, paddingTop: 3 }}>{label.toUpperCase()}</span>
      <span style={{ flex: 1, fontWeight: 300 }}>{val}</span>
    </div>
  ) : null;

  return (
    <div className="hq" style={{ position: "fixed", inset: 0, zIndex: 100, background: B.c.bg, color: B.c.ink, overflowY: "auto", "--focus": B.c.accent }}>
      <div style={{ position: "sticky", top: 0, zIndex: 5, background: "#3B3325", display: "flex", justifyContent: "space-between", alignItems: "center", padding: "9px 16px" }}>
        <span className="hq-mono" style={{ fontSize: 8.5, letterSpacing: 2.5, color: "#E8D5A6" }}>PORTAL PREVIEW — WHAT {firstName.toUpperCase()} WILL SEE</span>
        <button onClick={onExit} className="hq-mono"
          style={{ padding: "6px 14px", borderRadius: 3, border: "1px solid #E8D5A6", background: "transparent", color: "#E8D5A6", fontSize: 9, letterSpacing: 2 }}>
          EXIT
        </button>
      </div>

      <div style={{
        background: B.key === "vg"
          ? `radial-gradient(140% 180% at 50% -40%, ${B.c.deep2} 0%, ${B.c.deep} 70%)`
          : `linear-gradient(160deg, ${B.c.deep} 20%, ${B.c.deep2} 100%)`,
        textAlign: "center", padding: "30px 20px 26px", color: B.c.soft,
      }}>
        <div style={{ display: "grid", placeItems: "center", marginBottom: 12 }}>
          <Monogram B={B} text={firstName.charAt(0)} size={62} fill={B.c.gold} />
        </div>
        <div style={{ fontFamily: B.display, fontStyle: "italic", fontSize: 16, color: B.c.gold }}>Welcome back,</div>
        <div style={{ fontFamily: B.display, fontSize: 30, fontWeight: 600, letterSpacing: 1, lineHeight: 1.1 }}>{client.name}</div>
        <hr className="lux-rule" style={{ width: 120, margin: "12px auto 10px", "--metal-mid": B.c.gold }} />
        <div className="hq-mono" style={{ fontSize: 8.5, letterSpacing: 3, color: B.c.gold }}>
          {client.biz?.RE && "◈ PAIGE SWOPE REALTY   "}{client.biz?.PP && "♛ PAGEANT PERFECT   "}{client.biz?.VG && "✦ VELVET GLOW"}
        </div>
      </div>

      <div style={{ maxWidth: 560, margin: "0 auto", padding: "6px 16px 60px" }}>
        <SectionLabel>MY UPCOMING VISITS · {upcoming.length}</SectionLabel>
        {upcoming.length === 0 && <p style={{ fontSize: 13.5, fontWeight: 300, color: B.c.faint }}>Nothing booked yet — reserve your next visit below.</p>}
        {upcoming.map((e) => (
          <div key={e.id} style={{ ...card, padding: "13px 15px", marginBottom: 8, borderLeft: `2px solid ${B.c.accent}` }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 8 }}>
              <div style={{ fontWeight: 500, fontSize: 14.5 }}><span style={{ color: B.c.accent, marginRight: 6 }}>{EVENT_TYPES[e.type]?.mark}</span>{e.title}</div>
              <div className="hq-mono" style={{ fontSize: 10, color: B.c.faint, whiteSpace: "nowrap" }}>{prettyDate(e.date)} · {prettyTime(e.time)}</div>
            </div>
            <button onClick={() => downloadICS(`${e.title.replace(/[^a-z0-9]/gi, "-").toLowerCase()}.ics`, [{ title: e.title, date: e.date, time: e.time || "", durMin: e.durMin }])}
              className="hq-mono" style={{ border: "none", background: "none", color: B.c.accent, fontSize: 9.5, letterSpacing: 2, padding: 0, marginTop: 7, fontWeight: 500 }}>
              ADD TO MY IPHONE
            </button>
          </div>
        ))}

        {client.biz?.PP && (
          <>
            <SectionLabel>MY PAGEANT SEASON</SectionLabel>
            {myPageants.length === 0 && <p style={{ fontSize: 13.5, fontWeight: 300, color: B.c.faint }}>No pageants on the calendar yet — Coach Paige will add you when it's time.</p>}
            {myPageants.map((p) => {
              const g = (p.girls || []).find((x) => x.name.toLowerCase() === client.name.toLowerCase());
              return (
                <div key={p.id} style={{ ...card, padding: "14px 16px", marginBottom: 10, borderLeft: `2px solid ${B.c.gold}` }}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 8 }}>
                    <div style={{ fontFamily: B.display, fontWeight: 600, fontSize: 17 }}><span style={{ color: B.c.accent }}>♛</span> {p.name}</div>
                    {p.date && <span className="hq-mono" style={{ fontSize: 9, letterSpacing: 2, color: B.c.accent, fontWeight: 500 }}>{daysOut(p.date) === 0 ? "TODAY" : `IN ${daysOut(p.date)} DAYS`}</span>}
                  </div>
                  <div className="hq-mono" style={{ fontSize: 9.5, letterSpacing: 1, color: B.c.faint, marginTop: 3 }}>{p.date}{p.location ? ` · ${p.location.toUpperCase()}` : ""}</div>
                  {g?.category && <div className="hq-mono" style={{ fontSize: 9, letterSpacing: 2, color: B.c.accent, marginTop: 6 }}>COMPETING · {g.category.toUpperCase()}</div>}
                </div>
              );
            })}
          </>
        )}

        {client.biz?.RE && (
          <>
            <SectionLabel>MY HOME JOURNEY</SectionLabel>
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              <a href={`mailto:${BRANDS.re.email}?subject=Home valuation request`} style={{ ...card, padding: "13px 15px", textDecoration: "none", color: B.c.ink, borderLeft: `2px solid ${BRANDS.re.c.accent}` }}>
                <div style={{ fontWeight: 500, fontSize: 14.5 }}>◈ Request a home valuation</div>
                <div style={{ fontSize: 12.5, fontWeight: 300, color: B.c.faint, marginTop: 2 }}>Paige will reach out personally with what your home is worth.</div>
              </a>
              <a href={BRANDS.re.financeUrl} target="_blank" rel="noreferrer" style={{ ...card, padding: "13px 15px", textDecoration: "none", color: B.c.ink, borderLeft: `2px solid ${BRANDS.re.c.accent}` }}>
                <div style={{ fontWeight: 500, fontSize: 14.5 }}>◈ Financing &amp; pre-approval</div>
                <div style={{ fontSize: 12.5, fontWeight: 300, color: B.c.faint, marginTop: 2 }}>The Henderson Team — $500 off closing costs for coaching &amp; glow clients</div>
              </a>
            </div>
          </>
        )}

        <SectionLabel>RESERVE</SectionLabel>
        <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
          {client.biz?.PP && (
            <a href={BRANDS.pp.bookBase} target="_blank" rel="noreferrer"
              style={{ flex: 1, minWidth: 150, textAlign: "center", padding: "13px 14px", borderRadius: 4, background: BRANDS.pp.c.metal, color: BRANDS.pp.c.deep, fontWeight: 600, fontSize: 11, letterSpacing: 2, textTransform: "uppercase", textDecoration: "none" }}>
              ♛ Book a lesson
            </a>
          )}
          {client.biz?.VG && (
            <a href={BRANDS.vg.bookBase} target="_blank" rel="noreferrer"
              style={{ flex: 1, minWidth: 150, textAlign: "center", padding: "13px 14px", borderRadius: 4, background: BRANDS.vg.c.metal, color: BRANDS.vg.c.deep, fontWeight: 600, fontSize: 11, letterSpacing: 2, textTransform: "uppercase", textDecoration: "none" }}>
              ✦ Book a glow
            </a>
          )}
          {client.biz?.RE && (
            <a href={`tel:+1${BRANDS.re.phone}`}
              style={{ flex: 1, minWidth: 150, textAlign: "center", padding: "13px 14px", borderRadius: 4, background: BRANDS.re.c.metal, color: BRANDS.re.c.deep, fontWeight: 600, fontSize: 11, letterSpacing: 2, textTransform: "uppercase", textDecoration: "none" }}>
              ◈ Call Paige
            </a>
          )}
        </div>

        <SectionLabel>ADD MY OWN EVENT</SectionLabel>
        <div style={{ ...card, padding: 15 }}>
          <p style={{ fontSize: 12.5, fontWeight: 300, color: B.c.faint, margin: "0 0 10px" }}>
            Have a recital, game, closing date, or family event Paige should plan around? Add it here — it shows on her calendar too.
          </p>
          <div style={{ display: "flex", gap: 8, marginBottom: 8 }}>
            <input style={{ ...input, flex: 1.4 }} placeholder="Event — e.g., dance recital" value={ev.title} onChange={(e) => setEv({ ...ev, title: e.target.value })} />
          </div>
          <div style={{ display: "flex", gap: 8, marginBottom: 10 }}>
            <input style={{ ...input, flex: 1.2 }} type="date" value={ev.date} onChange={(e) => setEv({ ...ev, date: e.target.value })} />
            <input style={{ ...input, flex: 1 }} type="time" value={ev.time} onChange={(e) => setEv({ ...ev, time: e.target.value })} />
          </div>
          <button onClick={addMyEvent} disabled={!ev.title.trim() || !ev.date}
            style={{ width: "100%", padding: 13, borderRadius: 4, border: "none", background: ev.title.trim() && ev.date ? B.c.accent : "#CBC2B4", color: "#fff", fontWeight: 500, fontSize: 12, letterSpacing: 2, textTransform: "uppercase" }}>
            {added ? "Added to the calendar ✓" : "Share with Paige"}
          </button>
        </div>

        {(client.undertone || client.shade || client.skinNotes || client.division || client.goals) && (
          <>
            <SectionLabel>MY PROFILE</SectionLabel>
            <div style={{ ...card, padding: "14px 16px" }}>
              {infoRow("Undertone", client.undertone)}
              {infoRow("My shade", client.shade)}
              {infoRow("Skin notes", client.skinNotes)}
              {infoRow("Division", client.division)}
              {infoRow("Working on", client.goals)}
            </div>
          </>
        )}

        <SectionLabel>MY VISIT HISTORY · {history.length}</SectionLabel>
        {history.length === 0 && <p style={{ fontSize: 13.5, fontWeight: 300, color: B.c.faint }}>Your visits will appear here.</p>}
        {history.map((v) => (
          <div key={v.id} style={{ ...card, padding: "11px 14px", marginBottom: 8, borderLeft: `2px solid ${B.c.accent}` }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
              <div style={{ fontWeight: 500, fontSize: 14 }}>{v.service}</div>
              <div className="hq-mono" style={{ fontSize: 10, color: B.c.faint }}>{v.date}</div>
            </div>
            {v.style && <div className="hq-mono" style={{ fontSize: 9, letterSpacing: 2, color: B.c.accent, marginTop: 2 }}>{v.style.toUpperCase()}</div>}
          </div>
        ))}

        <p className="hq-mono" style={{ fontSize: 8.5, letterSpacing: 2, color: B.c.faint, textAlign: "center", lineHeight: 2, marginTop: 26 }}>
          PREVIEW ONLY — PRIVATE CLIENT LOGINS ARRIVE<br />WITH THE PORTAL PHASE
        </p>
      </div>
    </div>
  );
}

/* ================= CLIENTS ================= */
function ClientsTab({ B, clients, saveClients, openPortal, clearSamples, hasSamples }) {
  const { Field, input, Primary, chip, card, H } = useBrandBits(B);
  const [filter, setFilter] = useState("all");
  const [adding, setAdding] = useState(false);
  const blank = { name: "", biz: { PP: false, VG: false, RE: false }, about: "", phone: "", bigDate: "", bigLabel: "", undertone: "", shade: "", skinNotes: "", division: "", goals: "" };
  const [form, setForm] = useState(blank);
  const [open, setOpen] = useState(null);

  const shown = clients.filter((c) => filter === "all" || c.biz?.[filter]).sort((a, b) => a.name.localeCompare(b.name));
  const addClient = async () => {
    if (!form.name.trim()) return;
    await saveClients([...clients, { ...form, id: "c" + Date.now(), history: [] }]);
    setForm(blank); setAdding(false);
  };

  return (
    <div className="hq-fade">
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
        <H>Clientele</H>
        <button onClick={() => setAdding(!adding)} className="hq-mono"
          style={{ padding: "8px 16px", borderRadius: 3, border: "none", background: B.c.deep, color: B.c.gold, fontSize: 10, letterSpacing: 2 }}>
          {adding ? "CANCEL" : "+ ADD"}
        </button>
      </div>

      {hasSamples && (
        <div style={{ ...card, padding: "10px 14px", marginBottom: 14, display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10 }}>
          <span style={{ fontSize: 12, fontWeight: 300, color: B.c.faint }}>Sample data loaded — clients, receipts, listings, and appointments. Tap any VIEW PORTAL button.</span>
          <button onClick={clearSamples} className="hq-mono" style={{ padding: "6px 12px", borderRadius: 3, border: `1px solid ${B.c.faint}`, background: "transparent", color: B.c.faint, fontSize: 8.5, letterSpacing: 1.5, whiteSpace: "nowrap" }}>CLEAR SAMPLES</button>
        </div>
      )}

      <div style={{ display: "flex", gap: 6, marginBottom: 16, flexWrap: "wrap" }}>
        {[["all", "ALL"], ["PP", "♛ PAGEANT"], ["VG", "✦ GLOW"]].map(([v, lab]) => (
          <button key={v} className="hq-mono" style={chip(filter === v)} onClick={() => setFilter(v)}>{lab}</button>
        ))}
      </div>

      {adding && (
        <div className="hq-fade" style={{ ...card, padding: 18, marginBottom: 16 }}>
          <Field label="Name"><input style={input} value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></Field>
          <Field label="Client of">
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
              {[["PP", "♛ Pageant Perfect"], ["VG", "✦ Velvet Glow"]].map(([k, lab]) => (
                <button key={k} onClick={() => setForm({ ...form, biz: { ...form.biz, [k]: !form.biz[k] } })}
                  style={{ flex: 1, minWidth: 90, padding: "11px 8px", borderRadius: 4, fontSize: 12.5, fontWeight: 500, letterSpacing: 0.5, border: `1px solid ${form.biz[k] ? B.c.deep : B.c.line}`, background: form.biz[k] ? B.c.deep : "transparent", color: form.biz[k] ? B.c.gold : B.c.ink }}>
                  {lab}
                </button>
              ))}
            </div>
          </Field>
          <Field label="About them — what helps Paige know them">
            <textarea style={{ ...input, minHeight: 64 }} value={form.about} onChange={(e) => setForm({ ...form, about: e.target.value })}
              placeholder="School, favorite things, budget, timeline, allergies, mom's name…" />
          </Field>
          <Field label="Phone — for quick rebooking texts"><input style={input} type="tel" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} placeholder="(859) 555-1234" /></Field>
          <div style={{ display: "flex", gap: 10 }}>
            <div style={{ flex: 0.9 }}><Field label="Big day"><input style={input} type="date" value={form.bigDate} onChange={(e) => setForm({ ...form, bigDate: e.target.value })} /></Field></div>
            <div style={{ flex: 1.1 }}><Field label="What is it"><input style={input} value={form.bigLabel} onChange={(e) => setForm({ ...form, bigLabel: e.target.value })} placeholder="Wedding, prom, senior photos…" /></Field></div>
          </div>
          {form.biz.VG && (
            <>
              <div style={{ display: "flex", gap: 10 }}>
                <div style={{ flex: 1 }}><Field label="Undertone"><input style={input} value={form.undertone} onChange={(e) => setForm({ ...form, undertone: e.target.value })} placeholder="Warm / cool / neutral" /></Field></div>
                <div style={{ flex: 1 }}><Field label="Usual shade"><input style={input} value={form.shade} onChange={(e) => setForm({ ...form, shade: e.target.value })} placeholder="Medium, Rapid 1hr…" /></Field></div>
              </div>
              <Field label="Skin notes"><input style={input} value={form.skinNotes} onChange={(e) => setForm({ ...form, skinNotes: e.target.value })} placeholder="Sensitive skin, fades fast…" /></Field>
            </>
          )}
          {form.biz.PP && (
            <div style={{ display: "flex", gap: 10 }}>
              <div style={{ flex: 1 }}><Field label="Division"><input style={input} value={form.division} onChange={(e) => setForm({ ...form, division: e.target.value })} placeholder="e.g., Preteen" /></Field></div>
              <div style={{ flex: 1 }}><Field label="Goals / focus"><input style={input} value={form.goals} onChange={(e) => setForm({ ...form, goals: e.target.value })} placeholder="Interview, walk…" /></Field></div>
            </div>
          )}
          <Primary onClick={addClient} disabled={!form.name.trim()}>Save client</Primary>
        </div>
      )}

      {shown.length === 0 && !adding && (
        <div style={{ textAlign: "center", padding: "40px 20px", color: B.c.faint }}>
          <div style={{ fontFamily: B.display, fontSize: 30, color: B.c.accent }}>{B.mark}</div>
          <p style={{ fontSize: 14, fontWeight: 300 }}>No clients here yet. Each profile becomes a private client account when the portal opens.</p>
        </div>
      )}

      {shown.map((c) => (
        <div key={c.id} style={{ ...card, display: "flex", alignItems: "center", gap: 13, padding: "13px 15px", marginBottom: 10 }}>
          <button onClick={() => setOpen(c.id)} style={{ display: "flex", alignItems: "center", gap: 13, flex: 1, minWidth: 0, border: "none", background: "none", textAlign: "left", padding: 0, color: B.c.ink }}>
            <Monogram B={B} text={c.name.trim().charAt(0).toUpperCase()} />
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontFamily: B.display, fontWeight: 600, fontSize: 17 }}>
                {c.name}
                {c.sample && <span className="hq-mono" style={{ fontSize: 7.5, letterSpacing: 1.5, color: B.c.faint, marginLeft: 8, verticalAlign: "middle" }}>SAMPLE</span>}
              </div>
              <div className="hq-mono" style={{ fontSize: 9, color: B.c.faint, letterSpacing: 1.5, marginTop: 2, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                {(c.history || []).length} VISIT{(c.history || []).length === 1 ? "" : "S"}{c.shade ? ` · ${c.shade.toUpperCase()}` : ""}{c.division ? ` · ${c.division.toUpperCase()}` : ""}
                <span style={{ color: B.c.accent, letterSpacing: 2 }}>  {c.biz?.RE && "◈"}{c.biz?.PP && "♛"}{c.biz?.VG && "✦"}</span>
              </div>
            </div>
          </button>
          <button onClick={() => openPortal(c.id)} className="hq-mono"
            style={{ padding: "8px 11px", borderRadius: 3, border: `1px solid ${B.c.accent}`, background: "transparent", color: B.c.accent, fontSize: 8.5, letterSpacing: 1.5, whiteSpace: "nowrap", flexShrink: 0 }}>
            VIEW<br />PORTAL
          </button>
        </div>
      ))}

      {open && (
        <ClientDetail B={B} client={clients.find((x) => x.id === open)} onClose={() => setOpen(null)}
          onPortal={() => { openPortal(open); setOpen(null); }}
          onChange={async (u) => saveClients(clients.map((x) => (x.id === u.id ? u : x)))}
          onDelete={async () => { await saveClients(clients.filter((x) => x.id !== open)); setOpen(null); }} />
      )}
    </div>
  );
}

function ClientDetail({ B, client, onClose, onChange, onDelete, onPortal }) {
  const { input, Ghost } = useBrandBits(B);
  const [visit, setVisit] = useState({ date: new Date().toISOString().slice(0, 10), service: "", style: "", notes: "" });
  if (!client) return null;
  const history = (client.history || []).slice().sort((a, b) => (b.date || "").localeCompare(a.date || ""));
  const addVisit = () => {
    if (!visit.service.trim()) return;
    onChange({ ...client, history: [...(client.history || []), { id: "v" + Date.now(), ...visit }] });
    setVisit({ date: new Date().toISOString().slice(0, 10), service: "", style: "", notes: "" });
  };
  const infoRow = (label, val) => val ? (
    <div style={{ display: "flex", gap: 10, fontSize: 13.5, marginBottom: 5 }}>
      <span className="hq-mono" style={{ fontSize: 9, letterSpacing: 2, color: B.c.faint, minWidth: 92, paddingTop: 3 }}>{label.toUpperCase()}</span>
      <span style={{ flex: 1, fontWeight: 300 }}>{val}</span>
    </div>
  ) : null;

  return (
    <Sheet B={B} onClose={onClose}>
      <div style={{ display: "flex", alignItems: "center", gap: 13, marginBottom: 12 }}>
        <Monogram B={B} text={client.name.trim().charAt(0).toUpperCase()} size={48} />
        <div style={{ flex: 1 }}>
          <div style={{ fontFamily: B.display, fontSize: 23, fontWeight: 600 }}>{client.name}</div>
          <div className="hq-mono" style={{ fontSize: 9, letterSpacing: 2, color: B.c.accent, marginTop: 2 }}>
            {client.biz?.RE && "◈ REALTY   "}{client.biz?.PP && "♛ PAGEANT PERFECT   "}{client.biz?.VG && "✦ VELVET GLOW"}
          </div>
        </div>
      </div>

      <Ghost onClick={onPortal} style={{ width: "100%", textAlign: "center", marginBottom: 12 }}>Preview their portal</Ghost>

      {client.about && <p style={{ fontSize: 13.5, lineHeight: 1.6, fontWeight: 300, background: B.c.card, borderLeft: `2px solid ${B.c.accent}`, padding: "10px 14px", borderRadius: 4 }}>{client.about}</p>}
      {infoRow("Phone", client.phone)}
      {infoRow("Big day", client.bigDate ? `${client.bigDate}${client.bigLabel ? ` — ${client.bigLabel}` : ""}` : "")}
      {infoRow("Undertone", client.undertone)}
      {infoRow("Usual shade", client.shade)}
      {infoRow("Skin notes", client.skinNotes)}
      {infoRow("Division", client.division)}
      {infoRow("Goals", client.goals)}

      <div className="hq-mono" style={{ fontSize: 9, letterSpacing: 3, color: B.c.faint, margin: "18px 0 10px" }}>VISIT HISTORY · {history.length}</div>
      {history.map((v) => (
        <div key={v.id} style={{ background: B.c.card, border: `1px solid ${B.c.line}`, borderLeft: `2px solid ${B.c.accent}`, borderRadius: 6, padding: "10px 13px", marginBottom: 8 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
            <div style={{ fontWeight: 500, fontSize: 14 }}>{v.service}</div>
            <div className="hq-mono" style={{ fontSize: 10, color: B.c.faint }}>{v.date}</div>
          </div>
          {v.style && <div className="hq-mono" style={{ fontSize: 9, letterSpacing: 2, color: B.c.accent, marginTop: 2 }}>{v.style.toUpperCase()}</div>}
          {v.notes && <div style={{ fontSize: 12.5, fontWeight: 300, color: B.c.faint, marginTop: 3 }}>{v.notes}</div>}
        </div>
      ))}
      {history.length === 0 && <p style={{ fontSize: 13, fontWeight: 300, color: B.c.faint }}>No visits logged yet — every future booking lands here.</p>}

      <div className="hq-mono" style={{ fontSize: 9, letterSpacing: 3, color: B.c.faint, margin: "14px 0 10px" }}>LOG A VISIT</div>
      <div style={{ display: "flex", gap: 8, marginBottom: 8 }}>
        <input style={{ ...input, flex: 1 }} type="date" value={visit.date} onChange={(e) => setVisit({ ...visit, date: e.target.value })} />
        <input style={{ ...input, flex: 1.3 }} placeholder="Service" value={visit.service} onChange={(e) => setVisit({ ...visit, service: e.target.value })} />
      </div>
      <div style={{ display: "flex", gap: 8 }}>
        <input style={{ ...input, flex: 1 }} placeholder="Style / shade used" value={visit.style} onChange={(e) => setVisit({ ...visit, style: e.target.value })} />
        <input style={{ ...input, flex: 1 }} placeholder="Notes" value={visit.notes} onChange={(e) => setVisit({ ...visit, notes: e.target.value })} onKeyDown={(e) => e.key === "Enter" && addVisit()} />
      </div>
      <button onClick={addVisit} disabled={!visit.service.trim()}
        style={{ width: "100%", marginTop: 10, padding: 13, borderRadius: 4, border: "none", background: visit.service.trim() ? B.c.accent : "#CBC2B4", color: "#fff", fontWeight: 500, fontSize: 12, letterSpacing: 2, textTransform: "uppercase" }}>
        Save visit
      </button>

      <div style={{ display: "flex", gap: 10, marginTop: 18 }}>
        <button onClick={onClose} style={{ flex: 1, padding: 13, borderRadius: 4, border: `1px solid ${B.c.deep}`, background: "transparent", color: B.c.deep, fontWeight: 500, fontSize: 11, letterSpacing: 2, textTransform: "uppercase" }}>Close</button>
        <button onClick={onDelete} style={{ flex: 1, padding: 13, borderRadius: 4, border: "1px solid #8A4646", background: "transparent", color: "#8A4646", fontWeight: 500, fontSize: 11, letterSpacing: 2, textTransform: "uppercase" }}>Delete</button>
      </div>
    </Sheet>
  );
}

/* ================= REAL ESTATE PORTFOLIO ================= */
function EstateTab({ B, estate, saveEstate }) {
  const { Field, input, Primary, card, H } = useBrandBits(B);
  const [adding, setAdding] = useState(false);
  const blank = { name: "", type: "Listing", status: "", address: "", notes: "" };
  const [form, setForm] = useState(blank);
  const [open, setOpen] = useState(null);

  const addProp = async () => {
    if (!form.name.trim()) return;
    await saveEstate([...estate, { ...form, id: "re" + Date.now(), log: [] }]);
    setForm(blank); setAdding(false);
  };

  return (
    <div className="hq-fade">
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
        <H>Portfolio</H>
        <button onClick={() => setAdding(!adding)} className="hq-mono"
          style={{ padding: "8px 16px", borderRadius: 3, border: "none", background: B.c.deep, color: B.c.gold, fontSize: 10, letterSpacing: 2 }}>
          {adding ? "CANCEL" : "+ ADD"}
        </button>
      </div>
      <p style={{ fontSize: 13, fontWeight: 300, color: B.c.faint, margin: "0 0 14px" }}>
        Listings, buyers, and deals — status and a running log for each one.
      </p>

      {adding && (
        <div className="hq-fade" style={{ ...card, padding: 18, marginBottom: 16 }}>
          <Field label="Property / deal name"><input style={input} value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="e.g., Listing · 214 Maple Grove Ct" /></Field>
          <div style={{ display: "flex", gap: 10 }}>
            <div style={{ flex: 1 }}>
              <Field label="Type">
                <select style={input} value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value })}>
                  {["Listing", "Purchase", "Rental", "Flip", "Land", "Personal", "Other"].map((t) => <option key={t}>{t}</option>)}
                </select>
              </Field>
            </div>
            <div style={{ flex: 1 }}><Field label="Status"><input style={input} value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value })} placeholder="Active, under contract…" /></Field></div>
          </div>
          <Field label="Address"><input style={input} value={form.address} onChange={(e) => setForm({ ...form, address: e.target.value })} /></Field>
          <Field label="Notes"><textarea style={{ ...input, minHeight: 60 }} value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} placeholder="Price, terms, contacts, key dates…" /></Field>
          <Primary onClick={addProp} disabled={!form.name.trim()}>Save</Primary>
        </div>
      )}

      {estate.length === 0 && !adding && (
        <div style={{ textAlign: "center", padding: "40px 20px", color: B.c.faint }}>
          <div style={{ fontFamily: B.display, fontSize: 30, color: B.c.accent }}>◈</div>
          <p style={{ fontSize: 14, fontWeight: 300 }}>Nothing here yet — add a listing, buyer, or deal and keep its whole story in one place.</p>
        </div>
      )}

      {estate.map((p) => (
        <button key={p.id} onClick={() => setOpen(p.id)}
          style={{ ...card, width: "100%", textAlign: "left", padding: "15px 17px", marginBottom: 12, borderLeft: `2px solid ${B.c.accent}`, cursor: "pointer" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 8 }}>
            <div style={{ fontFamily: B.display, fontWeight: 600, fontSize: 17 }}>
              <span style={{ color: B.c.accent }}>◈</span> {p.name}
              {p.sample && <span className="hq-mono" style={{ fontSize: 7.5, letterSpacing: 1.5, color: B.c.faint, marginLeft: 8 }}>SAMPLE</span>}
            </div>
            <span className="hq-mono" style={{ fontSize: 9, letterSpacing: 2, color: B.c.accent, whiteSpace: "nowrap" }}>{p.type.toUpperCase()}</span>
          </div>
          <div className="hq-mono" style={{ fontSize: 10, letterSpacing: 1, color: B.c.faint, marginTop: 4 }}>
            {p.status ? p.status.toUpperCase() : "NO STATUS"}{p.address ? ` · ${p.address.toUpperCase()}` : ""} · {(p.log || []).length} LOG ENTRIES
          </div>
        </button>
      ))}

      {open && (
        <EstateDetail B={B} prop={estate.find((x) => x.id === open)} onClose={() => setOpen(null)}
          onChange={async (u) => saveEstate(estate.map((x) => (x.id === u.id ? u : x)))}
          onDelete={async () => { await saveEstate(estate.filter((x) => x.id !== open)); setOpen(null); }} />
      )}
    </div>
  );
}

function EstateDetail({ B, prop, onClose, onChange, onDelete }) {
  const { input } = useBrandBits(B);
  const [note, setNote] = useState("");
  if (!prop) return null;
  const log = (prop.log || []).slice().reverse();
  const addNote = () => {
    if (!note.trim()) return;
    onChange({ ...prop, log: [...(prop.log || []), { id: "lg" + Date.now(), date: new Date().toISOString().slice(0, 10), note }] });
    setNote("");
  };
  return (
    <Sheet B={B} onClose={onClose}>
      <div style={{ fontFamily: B.display, fontSize: 24, fontWeight: 600 }}><span style={{ color: B.c.accent }}>◈</span> {prop.name}</div>
      <div className="hq-mono" style={{ fontSize: 10, letterSpacing: 1.5, color: B.c.faint, margin: "5px 0 10px" }}>
        {prop.type.toUpperCase()}{prop.status ? ` · ${prop.status.toUpperCase()}` : ""}
      </div>
      {prop.address && <div style={{ fontSize: 13.5, fontWeight: 300, marginBottom: 6 }}>{prop.address}</div>}
      {prop.notes && <p style={{ fontSize: 13.5, lineHeight: 1.6, fontWeight: 300, background: B.c.card, borderLeft: `2px solid ${B.c.accent}`, padding: "10px 14px", borderRadius: 4 }}>{prop.notes}</p>}

      <div className="hq-mono" style={{ fontSize: 9, letterSpacing: 3, color: B.c.faint, margin: "16px 0 10px" }}>LOG · {log.length}</div>
      {log.map((l) => (
        <div key={l.id} style={{ background: B.c.card, border: `1px solid ${B.c.line}`, borderRadius: 6, padding: "10px 13px", marginBottom: 8, display: "flex", gap: 10, alignItems: "flex-start" }}>
          <span className="hq-mono" style={{ fontSize: 9, color: B.c.faint, paddingTop: 3, whiteSpace: "nowrap" }}>{l.date}</span>
          <span style={{ flex: 1, fontSize: 13.5, fontWeight: 300, lineHeight: 1.5 }}>{l.note}</span>
          <button onClick={() => onChange({ ...prop, log: prop.log.filter((x) => x.id !== l.id) })} style={{ border: "none", background: "none", color: B.c.faint, fontSize: 14, padding: 2 }}>✕</button>
        </div>
      ))}
      {log.length === 0 && <p style={{ fontSize: 13, fontWeight: 300, color: B.c.faint }}>No entries yet — showings, offers, repairs, payments, calls.</p>}

      <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
        <input style={{ ...input, flex: 1 }} placeholder="Add a log entry…" value={note} onChange={(e) => setNote(e.target.value)} onKeyDown={(e) => e.key === "Enter" && addNote()} />
        <button onClick={addNote} disabled={!note.trim()}
          style={{ padding: "0 18px", borderRadius: 4, border: "none", background: note.trim() ? B.c.accent : "#CBC2B4", color: "#fff", fontWeight: 500, fontSize: 11, letterSpacing: 2, textTransform: "uppercase" }}>Add</button>
      </div>

      <div style={{ display: "flex", gap: 10, marginTop: 18 }}>
        <button onClick={onClose} style={{ flex: 1, padding: 13, borderRadius: 4, border: `1px solid ${B.c.deep}`, background: "transparent", color: B.c.deep, fontWeight: 500, fontSize: 11, letterSpacing: 2, textTransform: "uppercase" }}>Close</button>
        <button onClick={onDelete} style={{ flex: 1, padding: 13, borderRadius: 4, border: "1px solid #8A4646", background: "transparent", color: "#8A4646", fontWeight: 500, fontSize: 11, letterSpacing: 2, textTransform: "uppercase" }}>Delete</button>
      </div>
    </Sheet>
  );
}

/* ================= VAULT ================= */
function VaultTab({ B, index, saveIndex, income, saveIncome, mileage, saveMileage, settings, saveSettings, directing, pageants, clients, estate, initialView = "expenses" }) {
  const { Field, input, Primary, Ghost, chip, card, H } = useBrandBits(B);
  const [view, setView] = useState(initialView);
  const fileRef = useRef(null);
  const [stage, setStage] = useState("idle");
  const [pending, setPending] = useState(null);
  const [error, setError] = useState("");
  const [bizFilter, setBizFilter] = useState("all");
  const [open, setOpen] = useState(null);
  const [openImg, setOpenImg] = useState(null);
  const rate = Number(settings.mileRate) || 0.7;

  const onFile = async (e) => {
    const file = e.target.files?.[0]; e.target.value = "";
    if (!file) return;
    setError(""); setStage("analyzing");
    try {
      const base64 = await compressImage(file);
      const analysis = await analyzeReceipt(base64);
      setPending({ base64, analysis }); setStage("review");
    } catch (err) { setError(err.message || "Couldn't read that receipt — try a clearer photo."); setStage("idle"); }
  };
  const saveReceipt = async () => {
    const a = pending.analysis; const id = "r" + Date.now();
    const meta = { id, vendor: a.vendor || "Unknown", date: a.date || new Date().toISOString().slice(0, 10), amount: Number(a.amount) || 0, category: a.category || "Uncategorized", biz: a.biz || "Personal", deductible: a.deductible || "possibly", note: a.note || "", tip: a.tip || "", savedAt: new Date().toISOString() };
    const ok = await saveJSON("receipt-img:" + id, { data: pending.base64 });
    if (!ok) { setError("Couldn't save the image — storage may be full."); return; }
    await saveIndex([meta, ...index]);
    setPending(null); setStage("idle");
  };
  const openReceipt = async (r) => { setOpen(r); setOpenImg(null); const img = await loadJSON("receipt-img:" + r.id); setOpenImg(img?.data || ""); };
  const del = async (r) => { try { await removeKey("receipt-img:" + r.id); } catch {} await saveIndex(index.filter((x) => x.id !== r.id)); setOpen(null); };

  const incBlank = { date: new Date().toISOString().slice(0, 10), biz: "RE", source: "", amount: "", method: "Square" };
  const [inc, setInc] = useState(incBlank);
  const addIncome = async () => {
    if (!inc.source.trim() || !inc.amount) return;
    await saveIncome([{ ...inc, id: "i" + Date.now(), amount: Number(inc.amount) || 0 }, ...income]);
    setInc(incBlank);
  };

  const miBlank = { date: new Date().toISOString().slice(0, 10), biz: "RE", purpose: "", miles: "" };
  const [mi, setMi] = useState(miBlank);
  const addMiles = async () => {
    if (!mi.purpose.trim() || !mi.miles) return;
    await saveMileage([{ ...mi, id: "m" + Date.now(), miles: Number(mi.miles) || 0 }, ...mileage]);
    setMi(miBlank);
  };

  const expTotal = (b) => index.filter((r) => r.biz === b && r.deductible === "likely").reduce((s, r) => s + (r.amount || 0), 0);
  const incTotal = (b) => income.filter((i) => i.biz === b).reduce((s, i) => s + (i.amount || 0), 0);
  const miTotal = (b) => mileage.filter((m) => m.biz === b).reduce((s, m) => s + m.miles, 0);

  const Totals = ({ get, suffix }) => (
    <div style={{ display: "flex", gap: 8, margin: "0 0 16px" }}>
      {BIZ_KEYS.map(([k, br]) => (
        <div key={k} style={{ ...card, flex: 1, padding: "10px 11px", borderTop: `2px solid ${br.c.accent}` }}>
          <div className="hq-mono" style={{ fontSize: 12.5, fontWeight: 500 }}>{get(k)}</div>
          <div className="hq-mono" style={{ fontSize: 7.5, color: B.c.faint, letterSpacing: 1, marginTop: 3, whiteSpace: "nowrap" }}>{br.mark} {br.short}{suffix}</div>
        </div>
      ))}
    </div>
  );

  const bizSelect = (val, set) => (
    <select style={{ ...input, flex: 1 }} value={val} onChange={set}>
      <option value="RE">◈ Realty</option><option value="PP">♛ Pageant Perfect</option><option value="VG">✦ Velvet Glow</option>
    </select>
  );

  return (
    <div className="hq-fade">
      <input ref={fileRef} type="file" accept="image/*" capture="environment" onChange={onFile} style={{ display: "none" }} />

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
        <H>The Vault</H>
        <Ghost onClick={() => exportBooksCSV(index, income, mileage, rate, directing)} style={{ padding: "8px 14px", fontSize: 9.5 }}>Export for accountant</Ghost>
      </div>

      <div style={{ display: "flex", gap: 7, marginBottom: 16 }}>
        {[["expenses", "EXPENSES"], ["income", "INCOME"], ["mileage", "MILEAGE"], ["trends", "TRENDS"], ["advisor", "ADVISOR"]].map(([v, lab]) => (
          <button key={v} className="hq-mono" style={{ ...chip(view === v), flex: 1, textAlign: "center", padding: "7px 4px", fontSize: 8.5 }} onClick={() => setView(v)}>{lab}</button>
        ))}
      </div>

      {view === "advisor" && (
        <AdvisorTab B={B} index={index} pageants={pageants} clients={clients} income={income} mileage={mileage} settings={settings} directing={directing} estate={estate} />
      )}

      {view === "trends" && <IncomeTrends B={B} income={income} />}

      {view === "expenses" && stage === "idle" && (
        <>
          <button onClick={() => fileRef.current?.click()}
            style={{ width: "100%", padding: "17px", borderRadius: 8, border: `1px dashed ${B.c.accent}`, background: B.c.card, color: B.c.deep, marginBottom: 14 }}>
            <span style={{ fontWeight: 500, fontSize: 13, letterSpacing: 2.5, textTransform: "uppercase" }}>Photograph a receipt</span>
            <div className="hq-mono" style={{ fontSize: 9, letterSpacing: 2, color: B.c.faint, marginTop: 5 }}>READ · CATEGORIZED · FILED UNDER ◈ ♛ OR ✦</div>
          </button>
          {error && <p style={{ color: "#8A4646", fontSize: 14 }}>{error}</p>}

          <Totals get={(k) => money(expTotal(k))} suffix="" />

          <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 16 }}>
            {[["all", "ALL"], ["RE", "◈ RE"], ["PP", "♛ PP"], ["VG", "✦ VG"], ["Personal", "PERSONAL"]].map(([v, lab]) => (
              <button key={v} className="hq-mono" style={chip(bizFilter === v)} onClick={() => setBizFilter(v)}>{lab}</button>
            ))}
          </div>

          {index.filter((r) => bizFilter === "all" || r.biz === bizFilter).length === 0 && (
            <p style={{ textAlign: "center", color: B.c.faint, fontSize: 14, fontWeight: 300, padding: "26px 10px" }}>
              {index.length === 0 ? "The vault awaits its first receipt." : "Nothing matches that filter."}
            </p>
          )}

          {index.filter((r) => bizFilter === "all" || r.biz === bizFilter).map((r) => (
            <button key={r.id} onClick={() => openReceipt(r)}
              style={{ ...card, width: "100%", textAlign: "left", padding: "13px 15px", marginBottom: 10, cursor: "pointer" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
                <div style={{ fontWeight: 500, fontSize: 15 }}>
                  {r.vendor}
                  {r.sample && <span className="hq-mono" style={{ fontSize: 7.5, letterSpacing: 1.5, color: B.c.faint, marginLeft: 8 }}>SAMPLE</span>}
                </div>
                <div className="hq-mono" style={{ fontWeight: 500, fontSize: 14 }}>{money(r.amount)}</div>
              </div>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 6, gap: 8 }}>
                <div className="hq-mono" style={{ fontSize: 9.5, color: B.c.faint, letterSpacing: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{r.date} · {String(r.category || "").toUpperCase()}</div>
                <div style={{ display: "flex", gap: 6, alignItems: "center", flexShrink: 0 }}><BizChip biz={r.biz} /><Stamp level={r.deductible} /></div>
              </div>
            </button>
          ))}
        </>
      )}

      {view === "expenses" && stage === "analyzing" && (
        <div style={{ textAlign: "center", paddingTop: 50 }}>
          <div style={{ fontFamily: B.display, fontSize: 24, fontWeight: 600 }}>Reading your receipt…</div>
          <div className="hq-mono" style={{ color: B.c.faint, fontSize: 9.5, letterSpacing: 3, marginTop: 10 }}>VENDOR · AMOUNT · ◈ ♛ OR ✦ · WRITE-OFF</div>
        </div>
      )}

      {view === "expenses" && stage === "review" && pending && (
        <div className="hq-fade" style={{ ...card, padding: 18 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
            <div className="hq-mono" style={{ fontSize: 9, letterSpacing: 3, color: B.c.faint }}>REVIEW &amp; SAVE</div>
            <div style={{ display: "flex", gap: 6 }}><BizChip biz={pending.analysis.biz} /><Stamp level={pending.analysis.deductible} /></div>
          </div>
          <img src={`data:image/jpeg;base64,${pending.base64}`} alt="Receipt" style={{ width: "100%", maxHeight: 200, objectFit: "contain", background: B.c.bg, borderRadius: 6, marginBottom: 13 }} />
          {(() => {
            const a = pending.analysis;
            const upd = (k, v) => setPending({ ...pending, analysis: { ...a, [k]: v } });
            return (
              <>
                <Field label="Vendor"><input style={input} value={a.vendor || ""} onChange={(e) => upd("vendor", e.target.value)} /></Field>
                <div style={{ display: "flex", gap: 10 }}>
                  <div style={{ flex: 1 }}><Field label="Amount"><input className="hq-mono" style={input} type="number" step="0.01" value={a.amount ?? ""} onChange={(e) => upd("amount", parseFloat(e.target.value))} /></Field></div>
                  <div style={{ flex: 1 }}><Field label="Date"><input style={input} type="date" value={a.date || ""} onChange={(e) => upd("date", e.target.value)} /></Field></div>
                </div>
                <div style={{ display: "flex", gap: 10 }}>
                  <div style={{ flex: 1 }}><Field label="Business">
                    <select style={input} value={a.biz} onChange={(e) => upd("biz", e.target.value)}>
                      <option value="RE">◈ Realty</option><option value="PP">♛ Pageant Perfect</option><option value="VG">✦ Velvet Glow</option><option value="Personal">Personal</option>
                    </select></Field></div>
                  <div style={{ flex: 1 }}><Field label="Verdict">
                    <select style={input} value={a.deductible} onChange={(e) => upd("deductible", e.target.value)}>
                      <option value="likely">Likely deductible</option><option value="possibly">Review</option><option value="unlikely">Personal</option>
                    </select></Field></div>
                </div>
                <Field label="Category"><input style={input} value={a.category || ""} onChange={(e) => upd("category", e.target.value)} /></Field>
                {a.note && <p style={{ fontSize: 13.5, lineHeight: 1.6, fontWeight: 300, background: B.c.bg, borderLeft: `2px solid ${B.c.accent}`, padding: "10px 14px", borderRadius: 4 }}>{a.note}</p>}
                {a.tip && <p style={{ fontSize: 12.5, lineHeight: 1.6, fontWeight: 300, color: B.c.faint }}>{a.tip}</p>}
              </>
            );
          })()}
          {error && <p style={{ color: "#8A4646", fontSize: 14 }}>{error}</p>}
          <Primary onClick={saveReceipt} style={{ marginTop: 8 }}>Save to vault</Primary>
          <button onClick={() => { setPending(null); setStage("idle"); }} style={{ width: "100%", marginTop: 10, padding: 12, background: "none", border: "none", color: B.c.faint, fontSize: 12, letterSpacing: 2, textTransform: "uppercase" }}>Discard</button>
        </div>
      )}

      {view === "income" && (
        <>
          <Totals get={(k) => money(incTotal(k))} suffix="" />
          <div style={{ ...card, padding: 16, marginBottom: 16 }}>
            <div style={{ display: "flex", gap: 8, marginBottom: 8 }}>
              <input style={{ ...input, flex: 1 }} type="date" value={inc.date} onChange={(e) => setInc({ ...inc, date: e.target.value })} />
              {bizSelect(inc.biz, (e) => setInc({ ...inc, biz: e.target.value }))}
            </div>
            <div style={{ display: "flex", gap: 8, marginBottom: 8 }}>
              <input style={{ ...input, flex: 1.4 }} placeholder="Client / service / commission" value={inc.source} onChange={(e) => setInc({ ...inc, source: e.target.value })} />
              <input className="hq-mono" style={{ ...input, flex: 0.8 }} type="number" step="0.01" placeholder="$" value={inc.amount} onChange={(e) => setInc({ ...inc, amount: e.target.value })} />
            </div>
            <select style={{ ...input, marginBottom: 10 }} value={inc.method} onChange={(e) => setInc({ ...inc, method: e.target.value })}>
              {["Square", "Commission check", "Cash", "Venmo", "Check", "Other"].map((m) => <option key={m}>{m}</option>)}
            </select>
            <Primary onClick={addIncome} disabled={!inc.source.trim() || !inc.amount}>Record income</Primary>
          </div>
          {income.length === 0 && <p style={{ textAlign: "center", color: B.c.faint, fontSize: 14, fontWeight: 300 }}>No income recorded yet — log commissions, lessons, and glows so profit sits beside the write-offs.</p>}
          {income.map((i) => (
            <div key={i.id} style={{ ...card, padding: "12px 15px", marginBottom: 8, display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10 }}>
              <div style={{ minWidth: 0 }}>
                <div style={{ fontWeight: 500, fontSize: 14.5 }}>{i.source}</div>
                <div className="hq-mono" style={{ fontSize: 9, letterSpacing: 1.5, color: B.c.faint, marginTop: 2 }}>{i.date} · {i.method?.toUpperCase()}</div>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 10, flexShrink: 0 }}>
                <BizChip biz={i.biz} />
                <span className="hq-mono" style={{ fontWeight: 500, fontSize: 14, color: "#4E6B4E" }}>{money(i.amount)}</span>
                <button onClick={() => saveIncome(income.filter((x) => x.id !== i.id))} style={{ border: "none", background: "none", color: B.c.faint, fontSize: 15, padding: 2 }}>✕</button>
              </div>
            </div>
          ))}
        </>
      )}

      {view === "mileage" && (
        <>
          <Totals get={(k) => `${miTotal(k).toLocaleString()}mi`} suffix="" />
          <div style={{ ...card, padding: 16, marginBottom: 16 }}>
            <div style={{ display: "flex", gap: 8, marginBottom: 8 }}>
              <input style={{ ...input, flex: 1 }} type="date" value={mi.date} onChange={(e) => setMi({ ...mi, date: e.target.value })} />
              {bizSelect(mi.biz, (e) => setMi({ ...mi, biz: e.target.value }))}
            </div>
            <div style={{ display: "flex", gap: 8, marginBottom: 10 }}>
              <input style={{ ...input, flex: 1.5 }} placeholder="Purpose — e.g., showings in Hamburg" value={mi.purpose} onChange={(e) => setMi({ ...mi, purpose: e.target.value })} />
              <input className="hq-mono" style={{ ...input, flex: 0.7 }} type="number" placeholder="Miles" value={mi.miles} onChange={(e) => setMi({ ...mi, miles: e.target.value })} />
            </div>
            <Primary onClick={addMiles} disabled={!mi.purpose.trim() || !mi.miles}>Log the drive</Primary>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 12 }}>
              <span className="hq-mono" style={{ fontSize: 9, letterSpacing: 2, color: B.c.faint }}>RATE $/MILE</span>
              <input className="hq-mono" style={{ ...input, width: 90, padding: "8px 10px" }} type="number" step="0.005" value={rate}
                onChange={(e) => saveSettings({ ...settings, mileRate: parseFloat(e.target.value) || 0 })} />
              <span style={{ fontSize: 11, fontWeight: 300, color: B.c.faint }}>verify the current IRS rate each year</span>
            </div>
          </div>
          {mileage.length === 0 && <p style={{ textAlign: "center", color: B.c.faint, fontSize: 14, fontWeight: 300 }}>No drives logged — showings, pageants, and on-location glows are all deductible miles.</p>}
          {mileage.map((m) => (
            <div key={m.id} style={{ ...card, padding: "12px 15px", marginBottom: 8, display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10 }}>
              <div style={{ minWidth: 0 }}>
                <div style={{ fontWeight: 500, fontSize: 14.5 }}>{m.purpose}</div>
                <div className="hq-mono" style={{ fontSize: 9, letterSpacing: 1.5, color: B.c.faint, marginTop: 2 }}>{m.date} · {m.miles} MI</div>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 10, flexShrink: 0 }}>
                <BizChip biz={m.biz} />
                <span className="hq-mono" style={{ fontWeight: 500, fontSize: 14 }}>{money(m.miles * rate)}</span>
                <button onClick={() => saveMileage(mileage.filter((x) => x.id !== m.id))} style={{ border: "none", background: "none", color: B.c.faint, fontSize: 15, padding: 2 }}>✕</button>
              </div>
            </div>
          ))}
        </>
      )}

      {open && (
        <Sheet B={B} onClose={() => setOpen(null)}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8, gap: 8 }}>
            <div style={{ fontFamily: B.display, fontSize: 22, fontWeight: 600 }}>{open.vendor}</div>
            <div style={{ display: "flex", gap: 6, flexShrink: 0 }}><BizChip biz={open.biz} /><Stamp level={open.deductible} /></div>
          </div>
          <div className="hq-mono" style={{ fontSize: 10.5, color: B.c.faint, letterSpacing: 1.5, marginBottom: 12 }}>{open.date} · {money(open.amount)} · {String(open.category || "").toUpperCase()}</div>
          {openImg === null ? (
            <div className="hq-mono" style={{ textAlign: "center", padding: 30, color: B.c.faint, fontSize: 10, letterSpacing: 3 }}>LOADING…</div>
          ) : openImg ? (
            <img src={`data:image/jpeg;base64,${openImg}`} alt={`Receipt from ${open.vendor}`} style={{ width: "100%", borderRadius: 8, background: B.c.card }} />
          ) : (
            <p style={{ color: B.c.faint, fontSize: 13, textAlign: "center", fontWeight: 300 }}>No photo on file for this one{open.sample ? " — sample receipts are text-only" : ""}.</p>
          )}
          {open.note && <p style={{ fontSize: 13.5, lineHeight: 1.6, fontWeight: 300, background: B.c.card, borderLeft: `2px solid ${B.c.accent}`, padding: "10px 14px", borderRadius: 4 }}>{open.note}</p>}
          {open.tip && <p style={{ fontSize: 12.5, color: B.c.faint, lineHeight: 1.6, fontWeight: 300 }}>{open.tip}</p>}
          <div style={{ display: "flex", gap: 10, marginTop: 14 }}>
            <button onClick={() => setOpen(null)} style={{ flex: 1, padding: 13, borderRadius: 4, border: `1px solid ${B.c.deep}`, background: "transparent", color: B.c.deep, fontWeight: 500, fontSize: 11, letterSpacing: 2, textTransform: "uppercase" }}>Close</button>
            <button onClick={() => del(open)} style={{ flex: 1, padding: 13, borderRadius: 4, border: "1px solid #8A4646", background: "transparent", color: "#8A4646", fontWeight: 500, fontSize: 11, letterSpacing: 2, textTransform: "uppercase" }}>Delete</button>
          </div>
        </Sheet>
      )}
    </div>
  );
}

/* ================= INCOME TRENDS (live analytics) ================= */
function IncomeTrends({ B, income }) {
  const { card, H } = useBrandBits(B);
  const now = new Date();
  const year = String(now.getFullYear());
  const ym = `${year}-${pad(now.getMonth() + 1)}`;
  const monthName = now.toLocaleDateString("en-US", { month: "long" });

  const sumBy = (pred, b) => income.filter((i) => pred(i) && (b ? i.biz === b : true)).reduce((s, i) => s + (i.amount || 0), 0);
  const inMonth = (i) => (i.date || "").startsWith(ym);
  const inYear = (i) => (i.date || "").startsWith(year);
  const monthly = Array.from({ length: 12 }, (_, m) => sumBy((i) => (i.date || "").startsWith(`${year}-${pad(m + 1)}`)));
  const maxM = Math.max(...monthly, 1);
  const letters = ["J", "F", "M", "A", "M", "J", "J", "A", "S", "O", "N", "D"];

  const PeriodCard = ({ label, pred }) => {
    const rows = [["♛ Pageant Perfect", sumBy(pred, "PP"), BRANDS.pp.c.accent], ["✦ Velvet Glow", sumBy(pred, "VG"), BRANDS.vg.c.accent], ["◈ Realty", sumBy(pred, "RE"), BRANDS.re.c.accent]];
    const total = rows.reduce((s, r) => s + r[1], 0);
    return (
      <div style={{ ...card, padding: "14px 16px", marginBottom: 12 }}>
        <div className="hq-mono" style={{ fontSize: 8.5, letterSpacing: 2.5, color: B.c.accent, marginBottom: 9, fontWeight: 500 }}>{label}</div>
        {rows.map(([lab, v, col]) => (
          <div key={lab} style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", padding: "4px 0" }}>
            <span style={{ fontSize: 13.5, fontWeight: 300 }}><span style={{ color: col }}>{lab.slice(0, 1)}</span>{lab.slice(1)}</span>
            <span className="hq-mono" style={{ fontSize: 13, fontWeight: 500 }}>{money(v)}</span>
          </div>
        ))}
        <hr className="lux-rule" style={{ margin: "7px 0" }} />
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
          <span className="hq-mono" style={{ fontSize: 9, letterSpacing: 2, color: B.c.faint }}>TOTAL</span>
          <span className="hq-mono" style={{ fontSize: 16, fontWeight: 500, color: "#4E6B4E" }}>{money(total)}</span>
        </div>
      </div>
    );
  };

  return (
    <div className="hq-fade">
      <PeriodCard label={`THIS MONTH · ${monthName.toUpperCase()} ${year}`} pred={inMonth} />
      <PeriodCard label={`THIS YEAR · ${year}`} pred={inYear} />

      <div style={{ ...card, padding: "14px 16px" }}>
        <div className="hq-mono" style={{ fontSize: 8.5, letterSpacing: 2.5, color: B.c.accent, marginBottom: 12, fontWeight: 500 }}>INCOME BY MONTH · {year}</div>
        <div style={{ display: "flex", alignItems: "flex-end", gap: 4, height: 92 }}>
          {monthly.map((v, m) => (
            <div key={m} style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 3, height: "100%", justifyContent: "flex-end" }}>
              {v > 0 && <div className="hq-mono" style={{ fontSize: 6, color: B.c.faint, whiteSpace: "nowrap" }}>{v >= 1000 ? `${Math.round(v / 100) / 10}k` : Math.round(v)}</div>}
              <div style={{ width: "100%", borderRadius: "3px 3px 0 0", height: Math.max(3, Math.round((v / maxM) * 64)), background: m === now.getMonth() ? B.c.accent : v > 0 ? (B.c.accent2 || B.c.rose) : B.c.line, opacity: m === now.getMonth() ? 1 : 0.75 }} />
              <div className="hq-mono" style={{ fontSize: 7, color: m === now.getMonth() ? B.c.accent : B.c.faint, fontWeight: m === now.getMonth() ? 600 : 400 }}>{letters[m]}</div>
            </div>
          ))}
        </div>
        <p style={{ fontSize: 11, fontWeight: 300, color: B.c.faint, margin: "10px 0 0" }}>Live from everything logged under Income — updates the moment a payout is recorded.</p>
      </div>
    </div>
  );
}

/* ================= ADVISOR ================= */
function AdvisorTab({ B, index, pageants, clients, income, mileage, settings, directing, estate }) {
  const { input, H } = useBrandBits(B);
  const [msgs, setMsgs] = useState([]);
  const [text, setText] = useState("");
  const [busy, setBusy] = useState(false);
  const bottomRef = useRef(null);
  useEffect(() => { bottomRef.current?.scrollIntoView({ behavior: "smooth" }); }, [msgs, busy]);

  const context = () => {
    const sums = {};
    index.forEach((r) => { const k = `${r.biz}:${r.category}`; sums[k] = (sums[k] || 0) + (r.amount || 0); });
    const incSums = { RE: 0, PP: 0, VG: 0 };
    income.forEach((i) => { incSums[i.biz] = (incSums[i.biz] || 0) + (i.amount || 0); });
    const miles = { RE: 0, PP: 0, VG: 0 };
    mileage.forEach((m) => { miles[m.biz] = (miles[m.biz] || 0) + m.miles; });
    const dir = directing.map((d) => ({
      name: d.name,
      feesPaid: (d.entries || []).reduce((s, e) => s + (e.paid ? e.fee || 0 : 0), 0),
      otherIncome: (d.income || []).reduce((s, i) => s + (i.amount || 0), 0),
      expenses: (d.expenses || []).reduce((s, x) => s + (x.amount || 0), 0),
      contestants: (d.entries || []).length,
    }));
    return `${BIZ_CONTEXT}
You are the in-app tax and business guide. Be warm, practical, concise (under 150 words unless asked for depth). The three businesses are separate 1099 activities — note when an expense belongs on one Schedule C vs another or should be split; directed-pageant income (entry fees, concessions) is also self-employment income to report. You are not a CPA; say so on high-stakes questions and recommend a professional for filings.
Expense totals by business:category → ${JSON.stringify(sums)}
Income totals → ${JSON.stringify(incSums)}. Mileage → ${JSON.stringify(miles)} miles at $${settings.mileRate}/mi.
Directed pageants → ${JSON.stringify(dir)}
Receipts: ${index.length}. Pageants tracked: ${pageants.length}. Clients: ${clients.length}. Portfolio items: ${estate.length}.`;
  };

  const send = async () => {
    const q = text.trim();
    if (!q || busy) return;
    const next = [...msgs, { role: "user", content: q }];
    setMsgs(next); setText(""); setBusy(true);
    try {
      const reply = await askClaude([
        { role: "user", content: context() },
        { role: "assistant", content: "Understood — I'll answer as Paige's in-app guide with that context." },
        ...next,
      ], 1000);
      setMsgs([...next, { role: "assistant", content: reply }]);
    } catch {
      setMsgs([...next, { role: "assistant", content: "That didn't go through — check your connection and try again." }]);
    } finally { setBusy(false); }
  };

  const starters = [
    "How are the books looking across all three businesses?",
    "What can I write off as a realtor?",
    "How do I report Miss Kentucky's Queen income?",
    "Can I deduct part of the house for the garage studio?",
  ];

  return (
    <div className="hq-fade" style={{ display: "flex", flexDirection: "column", minHeight: "60vh" }}>
      <div style={{ flex: 1 }}>
        {msgs.length === 0 && (
          <div style={{ textAlign: "center", paddingTop: 12 }}>
            <H>The Advisor</H>
            <p style={{ color: B.c.faint, fontSize: 13.5, fontWeight: 300, lineHeight: 1.6 }}>Knows all three businesses, the directed pageant, every receipt, the income, and the miles.</p>
            <div style={{ display: "flex", flexDirection: "column", gap: 8, marginTop: 10 }}>
              {starters.map((s) => (
                <button key={s} onClick={() => setText(s)} style={{ padding: "11px 14px", borderRadius: 4, border: `1px solid ${B.c.line}`, background: B.c.card, fontSize: 13.5, fontWeight: 300, color: B.c.ink }}>{s}</button>
              ))}
            </div>
          </div>
        )}
        {msgs.map((m, i) => (
          <div key={i} style={{ display: "flex", justifyContent: m.role === "user" ? "flex-end" : "flex-start", marginBottom: 10 }}>
            <div style={{
              maxWidth: "86%", padding: "12px 15px", fontSize: 14.5, lineHeight: 1.6, whiteSpace: "pre-wrap", fontWeight: m.role === "user" ? 400 : 300,
              borderRadius: 6, background: m.role === "user" ? B.c.deep : B.c.card, color: m.role === "user" ? B.c.soft : B.c.ink,
              border: m.role === "user" ? "none" : `1px solid ${B.c.line}`,
            }}>{m.content}</div>
          </div>
        ))}
        {busy && <div className="hq-mono" style={{ fontSize: 9.5, letterSpacing: 3, color: B.c.faint }}>COMPOSING…</div>}
        <div ref={bottomRef} />
      </div>
      <div style={{ display: "flex", gap: 8, marginTop: 12, position: "sticky", bottom: 84 }}>
        <input style={{ ...input, flex: 1 }} value={text} placeholder="Ask a question…" onChange={(e) => setText(e.target.value)} onKeyDown={(e) => e.key === "Enter" && send()} />
        <button onClick={send} disabled={busy || !text.trim()}
          style={{ padding: "0 20px", borderRadius: 4, border: "none", background: busy || !text.trim() ? "#C9C4BA" : B.c.deep, color: B.c.gold, fontWeight: 500, fontSize: 11, letterSpacing: 2, textTransform: "uppercase" }}>Send</button>
      </div>
      <p style={{ fontSize: 10.5, fontWeight: 300, color: B.c.faint, textAlign: "center", marginTop: 10 }}>
        AI guidance for planning only — confirm anything important with a CPA before filing.
      </p>
    </div>
  );
}
